#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nValue;  int nType;  } Queue_PolySH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPolySH(DefinePaint)  {  QueueP(Queue_PolySH);  //  double dValue = 0;  CShPolyHS& sh = (CShPolyHS&)PipeSH;  //  if ( IsTypeOK )  {		if ( p->nType == 0 )		{			char szText[128] = "Выбрано направление на циркуляцию";			if ( sh.SP==1 )				lstrcpy(szText,"Выбрано направление к КК-1");			else				if ( sh.SP==2 )					lstrcpy(szText,"Выбрано направление к КК-2");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}		else		if ( p->nType == 1 )		{			char szText[128] = "Выбрано направление на циркуляцию";			if ( sh.SP==1 )				lstrcpy(szText,"Выбрано направление к КК-3");			else				if ( sh.SP==2 )					lstrcpy(szText,"Выбрано направление к КК-4");			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}		else		if ( p->nType == 2 )		{			char szText[128];			int nComp=(sh.PV%4+1);			sprintf_s ( szText, sizeof(szText), "Выбран компрессор ГК-%d",nComp);			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}		else		if ( p->nType == 3 )		{			char szText[128];			int nComp=(sh.PV%4+1)+4;			sprintf_s ( szText, sizeof(szText), "Выбран компрессор ГК-%d",nComp);			::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );		}  }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPolySH(DefineTegs)  {  //  AddQueueEx(Queue_PolySH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPolySH;  p->nType=-1;  //  STegObj obj[] =    {    { 'I', "type" , &p->nType },    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSHPipe( def, id_PHS, teg[0].value, p, p->nValue );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~